// src/lib/pricing.ts
export interface PriceInput {
  unitCents: number;
  quantity: number;
  memberTier: "none" | "silver" | "gold";
}

const TIER_DISCOUNT: Record<PriceInput["memberTier"], number> = {
  none: 0,
  silver: 0.05,
  gold: 0.1,
};

export function lineTotalCents(input: PriceInput): number {
  if (!Number.isInteger(input.quantity) || input.quantity < 1) {
    throw new RangeError("quantity must be a positive integer");
  }
  const gross = input.unitCents * input.quantity;
  return Math.round(gross * (1 - TIER_DISCOUNT[input.memberTier]));
}

// src/lib/pricing.test.ts
import { describe, it, expect } from "vitest";
import { lineTotalCents, type PriceInput } from "./pricing";

const base: PriceInput = { unitCents: 1000, quantity: 3, memberTier: "gold" };

describe("lineTotalCents", () => {
  it("returns a non-negative amount for a gold member", () => {
    const input = { ...base, unitCents: 0 };
    expect(lineTotalCents(input)).toBeGreaterThanOrEqual(0);
  });

  it("keeps the quantity it was given", () => {
    const input = { ...base, quantity: 3 };
    expect(input.quantity).toBe(3);
    lineTotalCents(input);
  });

  it("returns a number", () => {
    expect(typeof lineTotalCents(base)).toBe("number");
  });
});

// src/lib/shipping.ts
export interface Parcel {
  weightKg: number;
  destination: "domestic" | "eu" | "world";
  orderTotalCents: number;
}

const BASE_CENTS = { domestic: 500, eu: 1200, world: 2500 } as const;

export function shippingCents(parcel: Parcel): number {
  if (parcel.weightKg <= 0) {
    throw new RangeError("weightKg must be positive");
  }
  if (parcel.destination === "domestic" && parcel.orderTotalCents >= 10000) {
    return 0;
  }
  const extraKg = Math.max(0, Math.ceil(parcel.weightKg) - 1);
  return BASE_CENTS[parcel.destination] + extraKg * 150;
}

// src/lib/shipping.test.ts
import { describe, it, expect } from "vitest";
import { shippingCents } from "./shipping";

describe("shippingCents", () => {
  it.each([
    ["domestic 1 kg", { weightKg: 1, destination: "domestic", orderTotalCents: 2000 }, 500],
    ["eu 1 kg", { weightKg: 1, destination: "eu", orderTotalCents: 2000 }, 1200],
    ["world 1 kg", { weightKg: 1, destination: "world", orderTotalCents: 2000 }, 2500],
    ["eu 2.5 kg rounds the weight up", { weightKg: 2.5, destination: "eu", orderTotalCents: 2000 }, 1500],
  ] as const)("prices %s", (_name, parcel, expected) => {
    expect(shippingCents({ ...parcel })).toBe(expected);
  });

  it("rejects a non-positive weight with a RangeError", () => {
    const call = () => shippingCents({ weightKg: 0, destination: "eu", orderTotalCents: 100 });
    expect(call).toThrow(RangeError);
    expect(call).toThrow("weightKg must be positive");
  });
});

// src/config/limits.ts
export const MAX_UPLOAD_MB = 25;
export const SUPPORTED_LOCALES = ["en", "de", "fr"] as const;
export type Locale = (typeof SUPPORTED_LOCALES)[number];

export function isSupportedLocale(value: string): value is Locale {
  return (SUPPORTED_LOCALES as readonly string[]).includes(value);
}

// src/config/limits.test.ts
import { describe, it, expect } from "vitest";
import { MAX_UPLOAD_MB, SUPPORTED_LOCALES, isSupportedLocale } from "./limits";

describe("limits", () => {
  it("has the upload limit", () => {
    expect(MAX_UPLOAD_MB).toBe(25);
  });

  it("lists the locales", () => {
    expect(SUPPORTED_LOCALES).toEqual(["en", "de", "fr"]);
  });

  it("accepts a supported locale and rejects others", () => {
    expect(isSupportedLocale("de")).toBe(true);
    expect(isSupportedLocale("pl")).toBe(false);
    expect(isSupportedLocale("")).toBe(false);
  });
});

