// src/lib/sku.ts
const SKU = /^[A-Z]{3}-\d{4}$/;

/** Validate a SKU such as ABC-1234. Throws TypeError for a non-string. */
export function isValidSku(value: unknown): boolean {
  if (typeof value !== "string") {
    throw new TypeError("isValidSku: value must be a string");
  }
  return SKU.test(value);
}

// src/lib/sku.test.ts
import { describe, it, expect } from "vitest";
import { isValidSku } from "./sku";

describe("isValidSku", () => {
  it("accepts three capitals, a hyphen and four digits", () => {
    expect(isValidSku("ABC-1234")).toBe(true);
  });

  it("rejects lowercase letters", () => {
    expect(isValidSku("abc-1234")).toBe(false);
  });

  it("rejects a three-digit number", () => {
    expect(isValidSku("ABC-123")).toBe(false);
  });

  it("rejects a non-string with a TypeError that names the contract", () => {
    expect(() => isValidSku(42)).toThrow(TypeError);
    expect(() => isValidSku(42)).toThrow("value must be a string");
  });
});

// src/lib/account.ts
export const ACCOUNT_ROLES = ["admin", "member", "guest"] as const;
export type AccountRole = (typeof ACCOUNT_ROLES)[number];

export function isAccountRole(value: string): value is AccountRole {
  return (ACCOUNT_ROLES as readonly string[]).includes(value);
}

/** Parse an age field. Throws RangeError for a negative or fractional value. */
export function parseAge(raw: string): number {
  const n = Number(raw);
  if (!Number.isInteger(n) || n < 0) {
    throw new RangeError("age must be a non-negative integer");
  }
  return n;
}

// src/lib/account.test.ts
import { describe, it, expect } from "vitest";
import { isAccountRole, parseAge } from "./account";

describe("isAccountRole", () => {
  it("accepts a known role", () => {
    expect(isAccountRole("member")).toBe(true);
  });

  it("rejects an unknown role", () => {
    expect(isAccountRole("owner")).toBe(false);
  });
});

describe("parseAge", () => {
  it("parses a whole number", () => {
    expect(parseAge("42")).toBe(42);
  });

  it("rejects a negative age with a RangeError", () => {
    expect(() => parseAge("-1")).toThrow(RangeError);
  });

  it("explains that the age must be a non-negative integer", () => {
    expect(() => parseAge("-1")).toThrow("age must be a non-negative integer");
  });

  it("rejects a fractional age with a RangeError", () => {
    expect(() => parseAge("1.5")).toThrow(RangeError);
  });
});

