// src/services/greeter.ts
export interface UserStore {
  getUser(id: string): { name: string; optedOut: boolean };
}

export interface Mailer {
  send(to: string, body: string): void;
}

export function greet(id: string, store: UserStore, mailer: Mailer): string {
  const user = store.getUser(id);
  if (user.optedOut) {
    return "skipped";
  }
  const body = `Hello, ${user.name}!`;
  mailer.send(id, body);
  return body;
}

// src/services/greeter.test.ts
import { beforeEach, describe, it, expect, vi } from "vitest";
import { greet } from "./greeter";

const store = { getUser: vi.fn() };
const mailer = { send: vi.fn() };

describe("greet", () => {
  beforeEach(() => {
    store.getUser.mockReset();
    mailer.send.mockReset();
  });

  it("greets a user by name and sends the same text", () => {
    store.getUser.mockReturnValue({ name: "Ada", optedOut: false });
    expect(greet("u1", store, mailer)).toBe("Hello, Ada!");
    expect(mailer.send).toHaveBeenCalledWith("u1", "Hello, Ada!");
  });

  it("sends nothing to an opted-out user", () => {
    store.getUser.mockReturnValue({ name: "Bob", optedOut: true });
    expect(greet("u2", store, mailer)).toBe("skipped");
    expect(mailer.send).not.toHaveBeenCalled();
  });
});
